import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"歸妹","description":"高島易斷 - 歸妹","frontmatter":{"title":"歸妹","description":"高島易斷 - 歸妹"},"headers":[],"relativePath":"classics/takashima/054.md","filePath":"classics/takashima/054.md"}'),i={name:"classics/takashima/054.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="歸妹" tabindex="-1">歸妹 <a class="header-anchor" href="#歸妹" aria-label="Permalink to “歸妹”">​</a></h1><h2 id="歸妹-1" tabindex="-1">歸妹 <a class="header-anchor" href="#歸妹-1" aria-label="Permalink to “歸妹”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>歸妹：徵兇，無攸利。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《歸妹》少長非偶，夫婦之不正也。女子以夫為家，在男曰娶，在女曰歸，故《漸》曰“女歸吉”，《鹹》曰“娶女吉”。“徵”者，往也，是私奔也，故兇，所謂鎖隙相窺，逾牆相從，父母國人皆賤之。女德若此，夫何利焉！故曰“無攸利”，是痛戒而深惡之也。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>澤上有雷，歸妹，君子以永終知敝。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>此卦反《漸》，上卦為雷，下卦為澤，雷動則澤水為之搖漾。以陰感陽，猶女子之挑而可動也，失身敗德，不謹其始，安能保其“永終”乎？君子見此象，知悅牽於私，動失其正，始既不善，敝即在後。欲防之於未然，故宜“永終”以“知敝”，斯不以妾為妻，不以賤妨貴。嫡庶正而名分嚴，足以維大義之不敝也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：一時發動，恐難持久。</p><p>○　問營商：貨價升動，賣客喜悅，但恐不能圖終。</p><p>○　問功名：進不以道，防有後悔。</p><p>○　問戰徵：地雷陡發，足以制勝，恐一勝以後，兵力疲敝，無以保終。</p><p>○　問婚姻：徒戀一時情慾之私者，難期百年偕老也。</p><p>○　問家宅：地磐有動，已嫁之婦，不宜同居母家。</p><p>○　問疾病：“永終”二字，獨於佔病不利，顯見命限已終。</p><p>○　問訟事：可以終結。</p><p>○　問六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>六爻以五為尊，是正嫡也，其他皆為娣，初爻在最下之位，故曰“歸妹以娣”。娣承嫡妻之命，不能專制，猶跛足之不能行，惟守為娣之分，行承順之道而已，故曰“跛能履”；《震》為足，《兌》為毀折，有跛之象。九居初，為當位，是能安於娣而在下，行不先人，知其無隕越也，故曰“徵吉”。就全卦論，以悅而動，女子感情悅之私，故其徵也兇；就一爻論，以剛居剛，女子有賢正之德，故其徵也，吉。《象傳》以“恆也”釋之，謂妹而為娣，禮之恆也；以“相承”釋之，謂百事承順，是以吉也。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：運途低微，祇可依人成事而已。</p><p>○　問營商：不能自主，聽命而行，幸得獲利，吉。</p><p>○　問功名：偏裨之位。</p><p>○　問戰徵：非主帥也，能以偏帥制勝，吉。</p><p>○　問家宅：此屋必是廊廡偏屋，吉。</p><p>○　問疾病：必是足疾，不良於行，身命無妨。</p><p>○　問六甲：生女，防有足疾。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>明治十六年，餘游上毛伊香保，得遇藤野正啟先生。先生當代鴻儒，夙精《易》理，與餘相知最久，茲得相聚客舍，晨夕晤談，意甚得也。一日先生正襟而言曰：幸為一佔僕之氣運。筮得《歸妹》之《解》。</p><p>先生精羲《易》，既得佔爻，自能詳判，餘復何言？然前餘為橫濱某商，佔得此爻，在此人久遊歐美各邦，通曉各國事情，歸國之後，橫濱某商店，遂僱為主管。其人正道，又能勤勉，凡財貨之出入，物品之優絀，以及時價之高低，罔不一一計劃，其用心之誠篤，有足使人感者。未幾商店解僱，一日某來請佔，筮得《歸妹》之《解》，餘為之再三玩索，乃得其解僱之由也。蓋娣者從姊而嫁，一切家政，皆當奉命而行，不得自主，譬跛者雖有其足，不能自行也。今某雖盡心從事，未免有專主之嫌，是以有咎。先生今日所佔，爻辭正同，乃知先生秉道履中，剛方素著，但於當今世衰道微，所如不合，反若娣之隨人，不能自主，先生能卑以自牧，故曰“徵吉”，此就爻辭而斷也。然餘又可慮者，以《歸妹》為歸魂之卦，至六爻為命終之年，先生固達人也，自初至上，為六年，先生須為注意。先生微笑曰：《易》理精妙，固如是也。後六年，先生果歿。</p><p>某官員來請佔氣運，筮得《歸妹》之《解》。</p><p>斷曰：初居爻下，娣居人下，爻象卑微，是不能出人頭地者也。足下佔氣運得此爻，知足下依人成事，不能獨斷獨行，譬如娣之從姊而嫁，一以順承為事，若欲擅自作為，反恐如跛者捷行，必致顛仆；不如隨人步趨，斯無隕越矣，故曰“徵吉”。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>此爻陽剛得中，亦娣之賢者也。下互《離》，《離》為目，上互《坎》，《坎》為疾，有眇之象。眇一目小也，兩目之視正，一目之視偏。妾媵則處於偏者也，不敢正視，故取“眇能視”為喻。二與五正應，二能側視，得其寵矣，然正未可以寵自恃，故又戒以“利幽人之貞”。“幽人”者，猶雲靜女也，女子行不逾閾，窺不出戶，有幽人之義焉。《象傳》曰“未變常也”，謂能守其道，安其分也。幽則至靜而不動，貞則至賢而不渝，幽人不以不遇變其道，女子不以失偶改其節，其致一也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：運途不正，宜幽貞自守。</p><p>○　問營商：以其窺察商情，有獨見之明，頗有暗得之利。</p><p>○　問功名：以高尚不仕為貴。</p><p>○　問戰徵：能察幽窺微，有料敵如神之妙。</p><p>○　問家宅：此宅最宜幽居。</p><p>○　問婚姻：此女宜作偏房，若在嫡室，恐反目不和。</p><p>○　問訟事：防有幽禁之災。</p><p>○　問六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>華族某訪餘別墅，時方霖雨，悶悶不樂，會招伊藤潮花，特設宴席，藉以侑酒。潮花見餘床上筮竹，問曰：主公好《易》乎？餘曰：然。潮花曰：抽生欲卜生命，請為一筮。筮得《歸妹》之《震》。</p><p>斷曰：《歸妹》者歸魂之卦，今自二爻至上爻為五年，今後五年，子命殆將終乎？上爻之辭曰：“女承筐無實，士刲羊無血”，“女承筐無實”者，謂家計赤貧，筐中無實也；“士刲羊無血”者，屍體之象也。潮花曰：主公之言誠當，諺雲“人生四十不為夭”，今吾已六十，命數亦不短矣。雖死期已迫，家計不可不預謀，由是奮然改革家政，計度產業，以期家室盈豐，得能積有餘資，實出自主公所賜也。當時談笑而去，後至五年六月，潮花竟爾病歿。</p><p>明治三十一年，佔臺灣總督府氣運，筮得《歸妹》之《震》。</p><p>斷曰：卦體下互《離》，《離》為目，目所以視也，曰“眇”，只可偏視而已。“幽人”者，幽閒貞靜之人也，謂人能幽閒貞靜，必無作亂之事矣，故曰“利幽人之貞”。今佔臺灣總督府政略，得此爻辭，按臺灣新入我版圖，一切風俗，難以一時遽《革》，只得另眼相視，在政府總宜以靜默鎮之，故曰“利幽人之貞”也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>“須”者，賤女之稱。三爻居《兌》之極，為悅之主，“歸妹以須”者，以之為須也。三以柔乘剛，務為悅人，故於其始歸也，降為之須，雖明知其未當，以故為抑之，不令其工妍獻媚，開以妾奪嫡之嫌，所以懲淫逸而正名分者，其旨嚴矣。迨三能反其悅之為，始得復歸娣之位，故曰“反歸以娣”。《象傳》曰“未當也”，謂陰柔不正，不當位也。《正義》以須為待時也，以三未當其時，則宜有待，故曰“歸妹以須”，既及其時，以娣乃行，故曰“反歸以娣”。亦通。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：運途尷尬，受人抑制，是宜忍耐，後可得伸。</p><p>○　問營商：貨價低落，不能獲利，過後可望提升。</p><p>○　問功名：所得卑微。</p><p>○　問婚姻：必非正娶。</p><p>○　問家宅：此屋非正宅，必是廊廡，地位低小。</p><p>○　問疾病：待時可愈。</p><p>○　問行人：且宜暫待，緩時可歸。</p><p>○　問訟事：待時可以斷結。</p><p>○　問六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>某縣人攜親友書來，佔求官之成否，筮得《歸妹》之《大壯》。</p><p>斷曰：鄭雲，“須，有才智之稱”；《正義》曰，“須，女謂賤妾也”，是有才智而屈居下位者也。今足下佔求官，得此爻辭，知足下與某顯官有舊，乞為代謀官階，不料某抑之，不與以相當之位置，而授以微末之官階，即“歸妹以須”之象也。足下宜順受之，切不可妄意幹進，後當必有升遷。“反歸以娣”，行有待也。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>九四以陽居陰，為動之主，動則急欲于歸，但《兌》為少女，故曰“妹”，未可先姊而行也，是宜待年於閨，故曰“歸妹愆期”。年及而歸，未為遲也，故曰“遲歸有時”。《詩·江汜》之篇，序謂媵有待年於國，而嫡不與之偕行，其後嫡悔而迎之，亦終歸矣，即可作此爻之註腳也。三爻主悅，求貴而得賤；四爻主動，求速而反遲，皆深戒“悅以動”之必兇也。告之以遲歸有待，所以遏其躁動之志，使知待時而行之為得也。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運；須知順時而動，行運有時，躁進無益。</p><p>○　問戰徵：最宜審時度勢，無取躁急輕進，致損兵力。</p><p>○　問營商：待時得價，自可獲利。</p><p>○　問功名：躁進必敗。</p><p>○　問婚姻：待年而歸。</p><p>○　問家宅：宅運未來，未可遷居。</p><p>○　問行人：一時不歸。</p><p>○　問訟事：宜緩，可了。</p><p>○　問失物：遲久可得。</p><p>○　問六甲：生男。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>某商人來，請佔買賣之機會，筮得《歸妹》之《臨》。</p><p>斷曰：女子待時而嫁，猶貨之待價而賈也。“愆期”者，謂期限已過，“遲歸”者，謂遲久可售也。足下佔買賣之機會，得此爻辭，爻象與佔象，辭意適合。“歸妹愆期”，由於姊猶未嫁，妹因不得先行，故宜遲歸待時，知足下必有前售之貨，未曾銷脫，故於後置之貨，行當遲遲有待。此所行不能不待，所售不能不遲也。遲之要自得利，可無憂焉。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“帝乙”者，殷紂之父；“君”者，小君之稱，謂嫡妻也；“袂”者，袖也，“月”者，太陰之精，以象婦德；“望”者，謂月之圓滿，“幾”者，近也。五爻居《震》之中，《震》長男，下與二應；二居《兌》，《兌》少女，是兄妹也。所謂“帝乙”，乃為《震》兄，“歸妹”者，是以天子之妹，下嫁於諸侯，故爻曰“其君”。《傳》曰“以貴行”，即所稱君夫人曰小君是也。卦體變《乾》成《兌》，《乾》為衣，故曰“袂”。《史記》“長袖善舞”，女子之態也，是袂足以取悅。月盈於望，八日《兌》見丁，十五《乾》盈甲，《兌》長至十五始盈，《乾》化《兌》；故曰“幾望”。《京房易傳》載湯嫁妹之詞曰：“陰之從陽，女之從夫，天地之義也。往事爾夫，必以禮義。”其訓以禮義者，即戒其不可以袂美取悅，亦不可以恃貴而妄動也。六五爻辰在卯，仲春之月，嫁娶男女之禮，故吉。《傳》曰“其位在中”，五居《震》中，二居《兌》中，以二嫁五，中與中應，其位悉當；且五爻最貴，故曰“以貴行也”。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：事事謙抑，不敢自誇，不敢自滿，運途得中，是以吉也。</p><p>○　問戰徵：降尊居賤，能得軍心；從月夜進兵，出敵不備，可得全勝。</p><p>○　問營商：前進貨品，不如後進者良，約在望前可售，必得高價。</p><p>○　問功名：如有兄弟，同出求名，弟必獲雋。</p><p>○　問婚姻：當有二女同歸，吉。</p><p>○　問家宅：宅位居中，當有喜事臨門。</p><p>○　問行人：望前可歸。</p><p>○　問疾病：半月可愈。</p><p>○　問六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>有友來訪，請佔某氏赴任吉凶，筮得《歸妹》之《兌》。</p><p>斷曰：“歸妹”者，以女從夫，猶士者出而從政也。今足下佔友赴任吉凶，而得《歸妹》五爻，細玩爻辭，知此友身分必貴，此次赴任．定是小受，如帝女之下嫁也。其才調之良，當必勝於前任，故曰“其君之袂，不如其娣之袂良”也。“月幾望”者，喻其設施之均到，政體之光明，有如三五之月也，而又不敢以諂媚取悅，不敢以貴盛自恃。以茲臨民，吉可知也。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“士”者，未娶之稱，“女”者，未嫁之稱。《士婚禮》雲，婦入三月而後祭行，上，宗廟爻，故曰祭。三月祭行，而後成婦，未承祭，猶稱女也。宗廟之禮，主婦奉筐，即《詩》所詠“於以盛之，維筐及莒”是也。《兌》為羊，少牢饋食，司馬刲羊，“刲”殺也，承筐刲羊，皆助祭事也。《易》例陽為實，陰為虛，三四復位，變《坤》為虛，故曰“承筐無實”；四互《坎》，《坎》為血卦，三四復位成《泰》，《坎》象不見。故曰“刲羊無血”。按祭禮，執盎者宗婦，薦豆者夫人，設黍者主婦，未聞有以娣妾從事者，使娣而與祭，是瀆倫也，欲以示寵，適以啟禍，亦何利焉？“永終知敝”者，可不戒哉！</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：萬事不利。</p><p>○　問戰徵：糗糧不備，戈矛不修，以斯從徵，必敗之道。</p><p>○　問營商：資本既虛，貨物又匱，奚以獲利？</p><p>○　問功名：空手求名，其何能得？</p><p>○　問婚姻：婚娶不正，維家之索。</p><p>○　問家宅：此宅家範不端，防有妾嫡紛爭之患。</p><p>○　問疾病：是虛勞失血之症，不治之象。</p><p>○　問失物：不得。</p><p>○　問六甲：生男。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>友人某來曰：近欲與友謀興一業，就餘私計，事既可喜，利亦頗豐，但未審吉凶如何？請為一筮。筮得《歸妹》之《兌》。</p><p>斷曰：卦體《兌》悅《震》動，卦象《兌》女《震》男，悅不以道，故夫婦配合多不利，而凡以資財合業者，亦可推相而知矣。今足下為謀事業，佔得此爻，爻辭曰“承筐無實”，“刲羊無血”。筐無實，是囊空也。血流行一身，猶財之流通一國，無血則羊死，無財則業敗。士與女為合業之人也，女既無實，士又無血，是財力兩空，其何能成業乎？故曰“無攸利”。</p>',112)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
